#!/usr/bin/env python3
"""
Round 164s (culprits), 4 October 2026. Needs round 163h.

Deep space, a ninth basemap, with its place names in Jost.
Adds its own block to map/app.js, a test block to map/test.mjs and the Jost
letter files in map/glyphs; changes nothing else.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 164s (4 October)\n\nNeeds round 163h (guards on its heading). No tiles patch. No app.js?v= bump.\nMade in a fourth chat (letter "s"); it adds one block of its own and touches\nno other block.\n\n- Asked 4 October, with two pictures (a swirl of glowing teal and blue\n  filaments with a muted magenta core; a navy chart of the solar system with\n  thin orbit rings and small spaced capitals): a ninth basemap, "Deep space"\n  (key space), after the others. Nothing cheesy: no planets, nebula pictures\n  or space fonts; nothing of either picture is copied. One block ("Deep\n  space, a ninth basemap" to "end of Deep space"), after the notes block;\n  layers outline-space-* (SPACE_IDS, SPACE_NAME_IDS), settings in SPACE.\n- Ground: near-black navy deeps with thin rings of light at 200, 1,000 and\n  2,000 m deep and a teal glow along every coast (AWS heights, sea-dem); land\n  indigo rising to a muted violet on high mountains; pale-cyan relief light\n  (outline-dem). Rivers as pale-blue filaments with a faint glow, roads as\n  thin tracks, borders dashed, a faint 15-degree grid (outline-space-grid,\n  GeoJSON made in code, gone by zoom 7) with the equator and prime meridian a\n  little stronger. Cities and towns as small points of light with a soft\n  halo (outline-space-dot, -dot-glow, sized by OpenMapTiles rank). Sky:\n  navy with a thin cobalt rim at the world view.\n- Names in the same theme: OpenFreeMap place, water_name, waterway,\n  mountain_peak and transportation_name in Jost (SIL OFL), small spaced\n  capitals: continents wide and faint lavender to zoom 3, countries muted\n  teal, cities pale bone, towns grey-blue, oceans and seas lavender italic,\n  lakes and rivers pale-blue italic, all on a navy halo. Letter files\n  map/glyphs/Jost-Light, Jost-Regular, Jost-LightItalic (made in the sandbox,\n  weights 300/400, 24 px SDF, buffer 3, radius 8, ranges 0-8959 and\n  65280-65535; Jost-README.md, Jost-OFL.txt). setGlyphs only if none set;\n  the picture labels are hidden only when these letters load (SPACE_GLYPHS,\n  namesRaster wrapped). Names and points kept over the layers, under the\n  news marks (spaceNamesOnTop). Place names box turns the words off.\n- Checked: layers pass the style-spec validator; rendered in Chromium\n  (MapLibre 5.24) on Natural Earth stand-in data, since OpenFreeMap and the\n  height tiles are blocked from the sandbox. Not seen against the live tiles.\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round164s: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 163h" not in h.read_text(encoding="utf-8"):
        sys.exit("round164s: round 163h must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round164s: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round164s: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round164s: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
